Below is a compact, self‑contained C++ program that demonstrates the most common operations you’ll use with `std::vector`.  
It covers

1. Declaration & construction  
2. Adding / inserting / removing elements  
3. Iterating (both indexed and range‑based)  
4. Querying size / capacity  
5. Using an initializer list and `reserve` to pre‑allocate  
6. Clearing a vector

```cpp
// vector_demo.cpp
#include <iostream>
#include <vector>
#include <string>

int main() {
    /* ----------------------------------------------------------
     * 1. Declare a vector of integers
     * ---------------------------------------------------------- */
    std::vector<int> numbers;          // empty vector

    /* ----------------------------------------------------------
     * 2. Push elements to the back (dynamic growth)
     * ---------------------------------------------------------- */
    numbers.push_back(10);
    numbers.push_back(20);
    numbers.push_back(30);

    /* ----------------------------------------------------------
     * 3. Query size and capacity
     *    - size()   : number of elements stored
     *    - capacity(): amount of storage already allocated
     * ---------------------------------------------------------- */
    std::cout << "Size:      " << numbers.size()     << '\n';
    std::cout << "Capacity:  " << numbers.capacity() << '\n';

    /* ----------------------------------------------------------
     * 4. Iterate over the vector
     *    a) Index based
     *    b) Range‑based (modern C++)
     * ---------------------------------------------------------- */
    std::cout << "Elements (index): ";
    for (std::size_t i = 0; i < numbers.size(); ++i)
        std::cout << numbers[i] << ' ';
    std::cout << '\n';

    std::cout << "Elements (range‑based): ";
    for (int n : numbers)
        std::cout << n << ' ';
    std::cout << '\n';

    /* ----------------------------------------------------------
     * 5. Insert an element in the middle
     * ---------------------------------------------------------- */
    numbers.insert(numbers.begin() + 1, 15);   // insert 15 before the 2nd element
    std::cout << "After insert: ";
    for (int n : numbers) std::cout << n << ' ';
    std::cout << '\n';

    /* ----------------------------------------------------------
     * 6. Remove the last element
     * ---------------------------------------------------------- */
    numbers.pop_back();
    std::cout << "After pop_back: ";
    for (int n : numbers) std::cout << n << ' ';
    std::cout << '\n';

    /* ----------------------------------------------------------
     * 7. Vector of strings using an initializer list
     * ---------------------------------------------------------- */
    std::vector<std::string> words{"hello", "world", "C++", "vectors"};
    std::cout << "Words: ";
    for (const auto& w : words) std::cout << w << ' ';
    std::cout << '\n';

    /* ----------------------------------------------------------
     * 8. Reserve capacity to avoid reallocations
     * ---------------------------------------------------------- */
    std::vector<int> big;
    big.reserve(1000);          // pre‑allocate space for 1000 ints
    for (int i = 0; i < 1000; ++i)
        big.push_back(i);
    std::cout << "big size: " << big.size()
              << ", capacity: " << big.capacity() << '\n';

    /* ----------------------------------------------------------
     * 9. Clear all elements
     * ---------------------------------------------------------- */
    big.clear();
    std::cout << "After clear, size: " << big.size() << '\n';

    return 0;
}
```

**Compile & run**

```bash
g++ -std=c++17 -O2 -Wall -Wextra vector_demo.cpp -o vector_demo
./vector_demo
```

**Output**

```
Size:      3
Capacity:  3
Elements (index): 10 20 30 
Elements (range‑based): 10 20 30 
After insert: 10 15 20 30 
After pop_back: 10 15 20 
Words: hello world C++ vectors 
big size: 1000, capacity: 1000
After clear, size: 0
```

This program touches on almost every operation you’ll need to get comfortable with `std::vector`. Feel free to tweak the code to explore other functions such as `erase`, `resize`, `swap`, or iterators (`begin()`, `end()`).
